async function retry(operation, attempts = 3) {
  try {
    return await operation();
  } catch (error) {
    if (attempts <= 1) throw error;
    return retry(operation, attempts - 1);
  }
}

function getAccess(user, resource) {
  if (!user) return "anonymous";
  if (!user.isActive) return "disabled";
  if (resource.ownerId === user.id) return "owner";
  // TODO: check whether this user has shared access
  return "denied";
}

def field_options(example, examples, regex, pattern, extra, json_schema_extra, v2, unset, warn):
    if example is not unset:
        warn('example deprecated')
    kwargs = dict(extra)
    if examples is not None:
        kwargs['examples'] = examples
    if regex is not None:
        warn('regex deprecated')
    selected = json_schema_extra or extra
    if v2:
        kwargs['pattern'] = pattern or regex
    else:
        kwargs['regex'] = pattern or regex
        kwargs.update(selected)
    filtered = {k: v for k, v in kwargs.items() if v is not unset}
    return filtered
